// tbd/twig-component-bundle: register controllers (inside vendor/)
const tbdControllers = require.context(
    '@symfony/stimulus-bridge/lazy-controller-loader!../vendor/tbd/twig-component-bundle/assets/controllers',
    true,
    /_controller\.[jt]sx?$/
);

for (const key of tbdControllers.keys()) {
    const mod = tbdControllers(key);

    const name = key
        .replace(/^\.\//, '')
        .replace(/\.[jt]sx?$/, '')
        .replace(/_controller$/, '')
        .replace(/\//g, '--')
        .replace(/_/g, '-');

    app.register(name, mod.default);
}

// tbd/twig-component-bundle: ensure Tailwind scans vendor Twig components
// Appended by the Flex recipe; safe to run multiple times.
try {
    const cfg = module.exports || {};
    const content = Array.isArray(cfg.content) ? cfg.content : [];

    const extras = [
        './vendor/tbd/twig-component-bundle/templates/**/*.html.twig',
        './vendor/tbd/twig-component-bundle/src/**/*.php',
    ];

    const next = [...content];
    for (const extra of extras) {
        if (!next.includes(extra)) {
            next.push(extra);
        }
    }

    cfg.content = next;
    module.exports = cfg;
} catch (e) {
    // noop
}
